solution.solution.rs:
use std::collections::BTreeMap;
use std::path::Path;

fn by_extension(paths: &[&str]) -> BTreeMap<String, Vec<String>> {
    let mut groups: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for p in paths {
        let path = Path::new(p);
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .map(|e| e.to_lowercase())
            .unwrap_or_else(|| "(none)".to_string());
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or(p).to_string();
        groups.entry(ext).or_default().push(name);
    }
    groups
}

unitTests:
test("groups", || {
    let g = by_extension(&["photos/a.JPG", "b.jpg", "notes/readme", "x/y/z.tar.gz"]);
    check_eq(g.keys().cloned().collect::<Vec<_>>(), vec!["(none)", "gz", "jpg"]);
    check_eq(g["jpg"].clone(), vec!["a.JPG", "b.jpg"]);
    check_eq(g["(none)"].clone(), vec!["readme"]);
    check_eq(g["gz"].clone(), vec!["z.tar.gz"]);
    check(by_extension(&[]).is_empty());
});

